import { ChangeDetectionStrategy, Component, computed, input, output } from '@angular/core';
import { PlanOffer } from '../../data/plan.model';

/**
 * One selectable plan: a native radio with a label over name and description; the label is stretched
 * (::after) so the whole card is the click target. Styled as a card (ui-ux-guidelines plan-card
 * recipe). The four rows (name, price, coverages, benefits) sit in the parent's subgrid.
 */
@Component({
  selector: 'app-plan-card',
  changeDetection: ChangeDetectionStrategy.OnPush,
  styleUrl: './plan-card.component.scss',
  template: `
    <div
      class="plan-card"
      [class.plan-card--recommended]="offer().plan.highlighted"
      [class.plan-card--selected]="selected()"
    >
      @if (offer().plan.highlighted) {
        <span class="plan-card__badge" aria-hidden="true">
          <svg viewBox="0 0 24 24" width="18" height="18" focusable="false">
            <path
              fill="currentColor"
              d="m12 2.5 2.9 6.1 6.6.8-4.9 4.6 1.3 6.6L12 17.3 6.1 20.6l1.3-6.6L2.5 9.4l6.6-.8z"
            />
          </svg>
          Recomendado
        </span>
      }
      <input
        class="plan-card__input"
        type="radio"
        [name]="groupName()"
        [value]="offer().plan.id"
        [checked]="selected()"
        [id]="inputId()"
        [attr.aria-label]="accessibleName()"
        [attr.aria-describedby]="priceId() + ' ' + descriptionId()"
        (change)="chosen.emit(offer().plan.id)"
      />
      <span class="plan-card__head">
        <span class="plan-card__radio" aria-hidden="true">
          <svg viewBox="0 0 16 16" width="14" height="14" focusable="false">
            <path
              d="M3 8.5l3.2 3.2L13 4.8"
              fill="none"
              stroke="currentColor"
              stroke-width="2.4"
              stroke-linecap="round"
              stroke-linejoin="round"
            />
          </svg>
        </span>
        <label class="plan-card__title" [for]="inputId()">
          <span class="plan-card__name">{{ offer().plan.name }}</span>
          <span class="plan-card__description" [id]="descriptionId()">{{ offer().plan.shortDescription }}</span>
        </label>
      </span>
      <span class="plan-card__price-row" [id]="priceId()">
        <span class="plan-card__price">{{ price().amount }}</span>
        <span class="plan-card__period">{{ price().period }}</span>
      </span>
      <span class="plan-card__section">
        @if (offer().plan.coverages.length > 0) {
          <span class="plan-card__section-title">Coberturas</span>
          <ul class="plan-card__list">
            @for (item of offer().plan.coverages; track $index) {
              <li class="plan-card__item">
                <svg viewBox="0 0 16 16" width="16" height="16" aria-hidden="true" focusable="false">
                  <path d="M3 8.5l3.2 3.2L13 4.8" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" />
                </svg>
                {{ item }}
              </li>
            }
          </ul>
        }
      </span>
      <span class="plan-card__section">
        @if (offer().plan.benefits.length > 0) {
          <span class="plan-card__section-title">Beneficios</span>
          <ul class="plan-card__list">
            @for (item of offer().plan.benefits; track $index) {
              <li class="plan-card__item">
                <svg viewBox="0 0 16 16" width="16" height="16" aria-hidden="true" focusable="false">
                  <path d="M3 8.5l3.2 3.2L13 4.8" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" />
                </svg>
                {{ item }}
              </li>
            }
          </ul>
        }
      </span>
    </div>
  `,
})
export class PlanCardComponent {
  readonly offer = input.required<PlanOffer>();
  readonly selected = input(false);
  /** Shared `name` of the radio group. */
  readonly groupName = input.required<string>();
  readonly chosen = output<string>();

  protected readonly inputId = computed(() => `plan-input-${this.offer().plan.id}`);
  /** Same source for every plan: the name, plus the recommended note when highlighted. */
  protected readonly accessibleName = computed(() => {
    const { name, highlighted } = this.offer().plan;
    return highlighted ? `${name}, plan recomendado` : name;
  });
  protected readonly descriptionId = computed(() => `plan-desc-${this.offer().plan.id}`);
  protected readonly priceId = computed(() => `plan-price-${this.offer().plan.id}`);
  /** "$ 145.000 / mes" shown as a large amount and a smaller period. */
  protected readonly price = computed(() => {
    const text = this.offer().formattedPrice;
    const cut = text.lastIndexOf(' / ');
    return cut < 0
      ? { amount: text, period: '' }
      : { amount: text.slice(0, cut), period: text.slice(cut) };
  });
}
:host {
  /* The card itself is the grid / slide item. */
  display: contents;
}

.plan-card {
  --plan-ring: var(--color-border);
  position: relative;
  display: grid;
  grid-template-rows: auto auto auto 1fr;
  flex: 1 1 auto;
  width: 100%;
  min-width: 0;
  padding: var(--space-6) var(--space-4);
  border: 1px solid var(--plan-ring);
  border-radius: 14px;
  background: var(--color-surface);
  cursor: pointer;

  /* From 992px the cards share the page grid, so the rows align across cards. */
  @media (min-width: 992px) {
    grid-row: span 4;
    grid-template-rows: subgrid;
    padding: var(--space-6);
  }

  &:hover {
    --plan-ring: var(--color-action);
  }

  &--recommended {
    --plan-ring: var(--color-brand);
    /* 5px top border instead of 1px: 4px less padding keeps the rows aligned. */
    padding-top: calc(var(--space-6) - 4px);
    border-top: 5px solid var(--color-brand);
    box-shadow: inset 0 0 0 1px var(--color-brand);

    &:hover {
      --plan-ring: var(--color-brand);
    }
  }

  &--selected,
  &--selected:hover {
    --plan-ring: var(--color-action);
    box-shadow: inset 0 0 0 1px var(--color-action);
  }

  &:has(.plan-card__input:focus-visible) {
    box-shadow:
      inset 0 0 0 1px var(--plan-ring),
      var(--focus-ring);
  }

  &__input {
    position: absolute;
    width: 1px;
    height: 1px;
    margin: 0;
    opacity: 0;
  }

  &__badge {
    position: absolute;
    top: -2.5px;
    left: 50%;
    z-index: 1;
    display: inline-flex;
    align-items: center;
    gap: var(--space-1);
    padding: 6px 18px;
    border-radius: var(--radius-pill);
    background: var(--color-cta);
    color: var(--color-on-cta);
    font-size: 16px;
    font-weight: 700;
    line-height: 1.2;
    white-space: nowrap;
    transform: translate(-50%, -50%);
    pointer-events: none;
  }

  &__head {
    display: flex;
    align-items: flex-start;
    gap: var(--space-3);
    padding-bottom: var(--space-4);
  }

  &__radio {
    flex: none;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 24px;
    height: 24px;
    margin-top: 2px;
    border: 2px solid var(--color-text-muted);
    border-radius: 50%;
    background: var(--color-surface);
    color: var(--color-surface);

    svg {
      opacity: 0;
    }
  }

  &--selected &__radio {
    border-color: var(--color-action);
    background: var(--color-action);

    svg {
      opacity: 1;
    }
  }

  &__title {
    cursor: pointer;
    display: flex;
    flex-direction: column;
    gap: var(--space-1);
    min-width: 0;
  }

  /* Stretched label: the whole card selects the radio (lists stay outside the label, R-09). */
  &__title::after {
    content: '';
    position: absolute;
    inset: 0;
    border-radius: 14px;
  }

  &__name {
    color: var(--color-action);
    font-size: 20px;
    font-weight: 700;
    line-height: 1.25;
  }

  &__description {
    color: var(--color-text-muted);
    font-size: 14px;
    font-weight: 500;
  }

  &__price-row {
    display: flex;
    flex-wrap: wrap;
    align-items: baseline;
    gap: var(--space-2);
    padding: var(--space-4) 0;
    border-top: 1px solid var(--color-border);
  }

  &__price {
    color: var(--color-brand);
    font-size: 32px;
    font-weight: 700;
    line-height: 1.1;
  }

  &__period {
    color: var(--color-text-muted);
    font-size: 14px;
    font-weight: 500;
  }

  &__section {
    display: block;
    min-width: 0;

    &:not(:empty) {
      padding-bottom: var(--space-4);
    }
  }

  &__section-title {
    display: block;
    margin-bottom: var(--space-2);
    color: var(--color-text);
    font-size: 14px;
    font-weight: 700;
  }

  &__list {
    display: flex;
    flex-direction: column;
    gap: var(--space-2);
    margin: 0;
    padding: 0;
    list-style: none;
  }

  &__item {
    display: flex;
    align-items: flex-start;
    gap: var(--space-2);
    color: var(--color-text);
    font-size: 14px;
    line-height: 1.4;

    svg {
      flex: none;
      margin-top: 2px;
      color: var(--color-brand);
    }
  }
}

