import {
  ChangeDetectionStrategy,
  Component,
  DestroyRef,
  ElementRef,
  ViewEncapsulation,
  afterNextRender,
  afterRenderEffect,
  computed,
  inject,
  signal,
  untracked,
} from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import Swiper from 'swiper';
import { A11y, Keyboard, Navigation, Pagination } from 'swiper/modules';
import { Subscription } from 'rxjs';
import { QuoteSessionStore } from '../../core/session/quote-session.store';
import { StepperComponent } from '../../shared/ui/stepper/stepper.component';
import { WizardCountry } from '../quote-wizard/wizard-country.service';
import { PlanCardComponent } from './components/plan-card/plan-card.component';
import { Plan, PlanOffer } from './data/plan.model';
import { PlanService } from './data/plan.service';
import { Ages, agesFromStep1 } from './pricing/ages-from-step1';
import { formatPrice } from './pricing/format-price';
import { simulatePrice } from './pricing/simulate-price';

/** Below Bootstrap's lg breakpoint the cards become a Swiper slider (R13). */
const SLIDER_QUERY = '(max-width: 991.98px)';

@Component({
  selector: 'app-plan-list-page',
  imports: [StepperComponent, PlanCardComponent],
  changeDetection: ChangeDetectionStrategy.OnPush,
  // None: Swiper builds some elements (dots) itself, so its classes must be styled globally.
  encapsulation: ViewEncapsulation.None,
  templateUrl: './plan-list.page.html',
  styleUrl: './plan-list.page.scss',
})
export class PlanListPage {
  private readonly wizardCountry = inject(WizardCountry);
  private readonly planService = inject(PlanService);
  private readonly session = inject(QuoteSessionStore);
  private readonly router = inject(Router);
  private readonly route = inject(ActivatedRoute);
  private readonly host = inject<ElementRef<HTMLElement>>(ElementRef);
  private readonly destroyRef = inject(DestroyRef);

  protected readonly steps = ['Tus datos', 'Elige tu plan', 'Resumen'];
  protected readonly loading = signal(true);
  protected readonly failed = signal(false);
  protected readonly slider = signal(false);
  protected readonly selectedId = signal<string | null>(null);
  private readonly plans = signal<Plan[]>([]);
  private readonly ages = signal<Ages>({ driverAge: null, vehicleAge: null });
  private loadSub: Subscription | null = null;
  private swiper: Swiper | null = null;

  protected readonly offers = computed<PlanOffer[]>(() => {
    const country = this.wizardCountry.country();
    if (!country) return [];
    const { driverAge, vehicleAge } = this.ages();
    return this.plans().map((plan) => {
      const finalPrice = simulatePrice(plan.basePrice, driverAge, vehicleAge, country);
      return { plan, finalPrice, formattedPrice: formatPrice(finalPrice, country) };
    });
  });
  protected readonly isEmpty = computed(
    () => !this.loading() && !this.failed() && this.offers().length === 0,
  );
  protected readonly actionsDelay = computed(() => this.offers().length + 1);

  constructor() {
    afterNextRender(() => this.host.nativeElement.querySelector<HTMLElement>('h1')?.focus());
    this.watchViewport();
    afterRenderEffect(() => {
      if (this.slider() && this.offers().length > 0) this.mountSwiper();
      else this.unmountSwiper();
    });
    this.destroyRef.onDestroy(() => {
      this.loadSub?.unsubscribe();
      this.unmountSwiper();
    });
    this.load();
  }

  protected load(): void {
    const country = this.wizardCountry.country();
    if (!country) return;
    this.loadSub?.unsubscribe();
    this.loading.set(true);
    this.failed.set(false);
    this.plans.set([]);
    this.loadSub = this.planService.load(country.code).subscribe({
      next: (plans) => {
        this.ages.set(agesFromStep1(this.session.readStep1(), new Date()));
        this.plans.set(plans);
        this.restoreChoice(plans);
        this.loading.set(false);
      },
      error: () => {
        this.failed.set(true);
        this.loading.set(false);
      },
    });
  }

  /** FR-009: keeps the saved choice only while the plan is still offered. */
  private restoreChoice(plans: Plan[]): void {
    const saved = this.session.readPlanId();
    if (saved && plans.some((plan) => plan.id === saved)) {
      this.selectedId.set(saved);
      return;
    }
    if (saved) this.session.clearPlan();
    this.selectedId.set(null);
  }

  protected choose(planId: string): void {
    this.selectedId.set(planId);
    this.session.savePlan(planId);
    const index = this.offers().findIndex((offer) => offer.plan.id === planId);
    if (index >= 0) this.swiper?.slideTo(index, this.reducedMotion() ? 0 : undefined);
  }

  protected backToStep1(): void {
    void this.router.navigate(['..'], { relativeTo: this.route });
  }

  protected continue(): void {
    if (!this.selectedId()) return;
    void this.router.navigate(['..', 'summary'], { relativeTo: this.route });
  }

  private watchViewport(): void {
    if (typeof matchMedia !== 'function') return;
    const query = matchMedia(SLIDER_QUERY);
    this.slider.set(query.matches);
    const onChange = (event: MediaQueryListEvent) => this.slider.set(event.matches);
    query.addEventListener('change', onChange);
    this.destroyRef.onDestroy(() => query.removeEventListener('change', onChange));
  }

  private reducedMotion(): boolean {
    return typeof matchMedia === 'function' && matchMedia('(prefers-reduced-motion: reduce)').matches;
  }

  private mountSwiper(): void {
    if (this.swiper) return;
    const root = this.host.nativeElement;
    const container = root.querySelector<HTMLElement>('.plan-list__viewport');
    if (!container) return;
    const offers = untracked(this.offers);
    const selectedId = untracked(this.selectedId);
    const chosen = offers.findIndex((offer) => offer.plan.id === selectedId);
    const highlighted = offers.findIndex((offer) => offer.plan.highlighted);
    this.swiper = new Swiper(container, {
      modules: [Navigation, Pagination, A11y, Keyboard],
      initialSlide: Math.max(0, chosen >= 0 ? chosen : highlighted),
      slidesPerView: 1.2,
      centeredSlides: true,
      spaceBetween: 16,
      loop: false,
      // R-08: no slide transition under prefers-reduced-motion.
      speed: this.reducedMotion() ? 0 : 300,
      breakpoints: { 768: { slidesPerView: 2.2 } },
      keyboard: { enabled: true, onlyInViewport: true },
      navigation: {
        prevEl: root.querySelector<HTMLElement>('.plan-list__nav--prev'),
        nextEl: root.querySelector<HTMLElement>('.plan-list__nav--next'),
      },
      pagination: {
        el: root.querySelector<HTMLElement>('.plan-list__dots'),
        clickable: true,
        // R-07: real buttons with a Spanish name.
        bulletElement: 'button',
        renderBullet: (index, className) =>
          `<button type="button" class="${className}" aria-label="Ir al plan ${index + 1} de ${offers.length}"></button>`,
      },
      a11y: {
        prevSlideMessage: 'Plan anterior',
        nextSlideMessage: 'Plan siguiente',
        paginationBulletMessage: `Ir al plan {{index}} de ${offers.length}`,
        firstSlideMessage: 'Este es el primer plan',
        lastSlideMessage: 'Este es el último plan',
        slideLabelMessage: 'Plan {{index}} de {{slidesLength}}',
      },
    });
  }

  private unmountSwiper(): void {
    this.swiper?.destroy(true, true);
    this.swiper = null;
  }
}
<section class="plan-list py-4">
  <div class="row justify-content-center">
    <div class="col-12 col-lg-8">
      <app-stepper [steps]="steps" [current]="2" />
    </div>
  </div>

  <header class="plan-list__header plan-list__reveal" style="--reveal-index: 0">
    <h1 class="plan-list__heading" tabindex="-1">Elige tu plan</h1>
  </header>

  @if (loading()) {
    <div class="plan-list__skeleton row g-3 g-lg-4" aria-busy="true">
      <span class="visually-hidden">Cargando planes…</span>
      @for (n of [1, 2, 3]; track n) {
        <div class="col-12 col-md-6 col-lg-4" aria-hidden="true">
          <div class="plan-list__skeleton-card">
            <span class="plan-list__skeleton-line plan-list__skeleton-line--title"></span>
            <span class="plan-list__skeleton-line"></span>
            <span class="plan-list__skeleton-line plan-list__skeleton-line--price"></span>
            <span class="plan-list__skeleton-line"></span>
            <span class="plan-list__skeleton-line"></span>
            <span class="plan-list__skeleton-line"></span>
          </div>
        </div>
      }
    </div>
  } @else if (failed()) {
    <div class="plan-list__error" role="alert">
      <p class="plan-list__error-title">
        <svg viewBox="0 0 24 24" width="24" height="24" aria-hidden="true" focusable="false">
          <circle cx="12" cy="12" r="10" fill="none" stroke="currentColor" stroke-width="2" />
          <path d="M12 7v6M12 16.5v.5" stroke="currentColor" stroke-width="2" stroke-linecap="round" />
        </svg>
        No pudimos cargar los planes.
      </p>
      <p class="plan-list__error-hint">Revisa tu conexión e inténtalo de nuevo.</p>
      <button type="button" class="button button--secondary" (click)="load()">Reintentar</button>
    </div>
  } @else if (isEmpty()) {
    <div class="plan-list__empty">
      <svg viewBox="0 0 48 48" width="48" height="48" aria-hidden="true" focusable="false">
        <path d="M24 5 8 11v11c0 10 6.8 17.6 16 21 9.2-3.4 16-11 16-21V11z" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linejoin="round" />
        <path d="M17 24h14" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" />
      </svg>
      <p class="plan-list__empty-title">No hay planes disponibles por ahora.</p>
      <p class="plan-list__empty-hint">Estamos actualizando nuestra oferta. Vuelve a intentarlo más tarde.</p>
      <button type="button" class="button button--secondary" (click)="backToStep1()">
        Volver a tus datos
      </button>
    </div>
  } @else {
    <fieldset class="plan-list__group">
      <legend class="visually-hidden">Elige tu plan</legend>
      <div class="plan-list__viewport" [class.swiper]="slider()">
        <div class="plan-list__track" [class.swiper-wrapper]="slider()">
          @for (offer of offers(); track offer.plan.id; let i = $index) {
            <div
              class="plan-list__item plan-list__reveal"
              [class.swiper-slide]="slider()"
              [style.--reveal-index]="i + 1"
            >
              <app-plan-card
                [offer]="offer"
                [selected]="selectedId() === offer.plan.id"
                groupName="plan"
                (chosen)="choose($event)"
              />
            </div>
          }
        </div>
      </div>
      @if (slider()) {
        <div class="plan-list__controls">
          <button type="button" class="plan-list__nav plan-list__nav--prev" aria-label="Plan anterior">
            <svg viewBox="0 0 16 16" width="16" height="16" aria-hidden="true" focusable="false">
              <path d="M10 3 5 8l5 5" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" />
            </svg>
          </button>
          <div class="plan-list__dots"></div>
          <button type="button" class="plan-list__nav plan-list__nav--next" aria-label="Plan siguiente">
            <svg viewBox="0 0 16 16" width="16" height="16" aria-hidden="true" focusable="false">
              <path d="m6 3 5 5-5 5" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" />
            </svg>
          </button>
        </div>
      }
    </fieldset>

    <div
      class="plan-list__actions plan-list__reveal d-flex flex-column-reverse flex-sm-row justify-content-sm-between gap-3"
      [style.--reveal-index]="actionsDelay()"
    >
      <button type="button" class="button button--secondary" (click)="backToStep1()">Volver</button>
      <button
        type="button"
        class="button button--cta"
        [disabled]="!selectedId()"
        (click)="continue()"
      >
        Continuar
        <svg viewBox="0 0 16 16" width="16" height="16" aria-hidden="true" focusable="false">
          <path d="M3 8h10M9 4l4 4-4 4" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" />
        </svg>
      </button>
    </div>
  }
</section>
.plan-list {
  /* Swiper theme */
  --swiper-theme-color: var(--color-action);

  &__header {
    margin: var(--space-6) 0 var(--space-4);
  }

  &__heading {
    margin: 0;
    color: var(--color-brand);
    font-size: 24px;
    font-weight: 700;

    &:focus {
      outline: none;
    }

    @media (min-width: 768px) {
      font-size: 32px;
    }
  }

  &__group {
    min-width: 0;
    margin: 0;
    padding: 0;
    border: 0;
  }

