   * benefits aligned across cards (agreed at Gate 2). Everything else uses Bootstrap row/col.
   * From 992px: three columns; each item spans 4 rows that the cards share (subgrid). */
  @media (min-width: 992px) {
    &__track {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      column-gap: var(--space-6);
      row-gap: 0;
    }

