    align-items: center;
    justify-content: center;
    width: 48px;
    height: 48px;
    padding: 0;
    border: 1px solid var(--color-brand);
    border-radius: 50%;
    background: var(--color-surface);
    color: var(--color-brand);
    cursor: pointer;

    &:hover:not(:disabled) {
      background: var(--color-surface-alt);
    }

    &:focus-visible {
      outline: none;
      box-shadow: var(--focus-ring);
    }

    &:disabled,
    &.swiper-button-disabled {
      border-color: transparent;
      background: var(--color-disabled-bg);
      color: var(--color-disabled-text);
      cursor: not-allowed;
    }
  }

  &__dots {
    display: flex;
    align-items: center;
  }

  /* R-07: each dot is a real button with a 48x48 hit area; the small dot is drawn by ::before. */
  &__dots .swiper-pagination-bullet {
    position: relative;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 48px;
    height: 48px;
    margin: 0;
    padding: 0;
    border: 0;
    border-radius: 50%;
    background: transparent;
    opacity: 1;
    cursor: pointer;

    &::before {
      content: '';
